import { type NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { deleteItem, getItem, updateItem, updateItemSchema } from '@/lib/items';

const idSchema = z.string().regex(/^itm_[\w-]{1,64}$/);

// `RouteContext<'/api/items/[id]'>` is a global type generated by `next dev`,
// `next build` or `next typegen`. `params` is a Promise in Next.js 16.
async function readId(context: RouteContext<'/api/items/[id]'>) {
  const { id } = await context.params;
  const parsed = idSchema.safeParse(id);
  return parsed.success ? parsed.data : null;
}

function notFound() {
  return NextResponse.json({ error: 'Item not found' }, { status: 404 });
}

// GET /api/items/itm_1
export async function GET(_request: NextRequest, context: RouteContext<'/api/items/[id]'>) {
  const id = await readId(context);
  const item = id ? getItem(id) : undefined;
  return item ? NextResponse.json(item) : notFound();
}

// PATCH /api/items/itm_1  {"quantity":7}
export async function PATCH(request: NextRequest, context: RouteContext<'/api/items/[id]'>) {
  const id = await readId(context);
  if (!id) return notFound();

  const body: unknown = await request.json().catch(() => null);
  const parsed = updateItemSchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json(
      { error: 'Invalid update', issues: z.flattenError(parsed.error) },
      { status: 422 },
    );
  }

  const item = updateItem(id, parsed.data);
  return item ? NextResponse.json(item) : notFound();
}

// DELETE /api/items/itm_1
export async function DELETE(_request: NextRequest, context: RouteContext<'/api/items/[id]'>) {
  const id = await readId(context);
  if (!id || !deleteItem(id)) return notFound();
  return new Response(null, { status: 204 });
}
